1	/**
2	 * The Super Productivity Witness calibration driver.
3	 *
4	 * There is no published journey for this application yet, and pinning one
5	 * before the live DOM has been read is what the TinyTranslator rounds spent
6	 * four passes undoing. This drives ONE lane of the bound production-static
7	 * output through the same host the proof will use, asks the page a list of
8	 * candidate questions, and prints every answer — including the refusals, which
9	 * are the measurement when a candidate is wrong.
10	 *
11	 * It publishes nothing, asserts nothing of its own, and is not part of any
12	 * receipt. Its only output is stdout.
13	 */
14	
15	import { basename, join, resolve } from 'pathe';
16	import { box, runBoxes } from '@async/witness';
17	import { joinURL } from 'ufo';
18	import { canonicalize } from '../../../core/src/receipts/canonicalize.ts';
19	import { witnessNodeFileSystem } from '../witness/node-filesystem.ts';
20	import { createPlaywrightWitnessHost } from '../witness/playwright-host.ts';
21	import { startStaticServer } from '../witness/real-app-run.ts';
22	
23	const root = resolve(import.meta.dirname, '../../../..');
24	
25	/**
26	 * The two bound lanes, exactly as the schema names them: the era lane is the
27	 * retained tree the u21 digest correction was recomputed from, and the migrated
28	 * lane is the offline-faithful rebuild u23 published.
29	 */
30	const laneRoots = {
31		baseline: join(
32			root,
33			'.versionless/cache/angular-super-productivity-v2-13-15-baseline/dist-run2',
34		),
35		migrated: join(root, '.versionless/stage/angular-super-productivity-v2-13-15-u18b/dist-23'),
36	} as const;
37	
38	const VIEWPORT = { width: 1280, height: 900 } as const;
39	
40	/**
41	 * The candidate selectors, read out of the application's own templates rather
42	 * than guessed: the shell, the work view, the add-task surface, the task list
43	 * and the two controls the time-tracking and theme legs would be anchored on.
44	 * Each is asked for as a count, so a candidate that does not resolve reports
45	 * zero rather than ending the pass.
46	 */
47	const CANDIDATES = [
48		'main-header',
49		'main-header .project-settings-btn',
50		'mat-drawer-container',
51		'side-nav',
52		'work-view-page',
53		'.work-view-header',
54		'add-task-bar',
55		'add-task-bar input',
56		'task-list',
57		'task-list task',
58		'task',
59		'task .title',
60		'task .play-btn',
61		'task .drag-handle',
62		'.task-list-wrapper',
63		'.completed-tasks-heading',
64		'backlog',
65		'split',
66		'banner',
67		'mat-progress-bar',
68	] as const;
69	
70	export async function calibrateAngularSuperProductivityLane(
71		lane: 'baseline' | 'migrated',
72	): Promise<void> {
73		const laneRoot = laneRoots[lane];
74		const receiptDir = join(
75			root,
76			'.versionless/stage/witness-angular-super-productivity-calibrate',
77			lane,
78		);
79		const staticServer = await startStaticServer(laneRoot, { profile: 'current-witness' });
80		const host = createPlaywrightWitnessHost({
81			chromiumExecutable: join(
82				root,
83				'.versionless/cache/react-boilerplate-v4/ms-playwright/chromium_headless_shell-1208/chrome-headless-shell-mac-arm64/chrome-headless-shell',
84			),
85			contextProfile: 'current-witness',
86			viewport: VIEWPORT,
87			// The application's own `index.html` links the Roboto stylesheet, so the
88			// seam is answered inside the context with an empty body exactly as the
89			// TinyTranslator vertical answers its icon stylesheet. Nothing leaves the
90			// machine, and the request is still observed.
91			transport: async () => ({
92				action: 'fulfill',
93				status: 200,
94				contentType: 'text/css',
95				body: Buffer.alloc(0),
96			}),
97		});
98		const counts: Record<string, number | string> = {};
99		let telemetry: unknown;
100		let storage: unknown;
101		let scroll: unknown;
102		const definition = box(`super-productivity-calibrate-${lane}`, async (context) => {
103			const page = await context.browser.visit(joinURL(staticServer.origin, '/'));
104			for (const selector of CANDIDATES) {
105				// Asked for as zero: a candidate that genuinely resolves nothing passes
106				// and is recorded as absent, and one that resolves reports its actual
107				// count in the refusal, which is the measurement being asked for.
108				try {
109					await context.expect.page.count(page, selector, 0);
110					counts[selector] = 0;
111				} catch (error: unknown) {
112					counts[selector] = (error instanceof Error ? error.message : String(error))
113						.split('\n')[0]!
114						.trim();
115				}
116			}
117			telemetry = await host.serviceWorkerTelemetry(10_000);
118			storage = await host.browserStorageKeys();
119			scroll = await host.viewportScroll();
120			await context.receipt.capture('calibration-complete');
121		});
122		let status = 'unknown';
123		let failure = '';
124		let receiptPath = '';
125		try {
126			const result = await runBoxes({
127				root: laneRoot,
128				boxes: [
129					{
130						file: join(laneRoot, 'versionless-runtime.box.ts'),
131						relativeFile: 'versionless-runtime.box.ts',
132						exportName: 'default',
133						box: definition,
134					},
135				],
136				receiptDir,
137				assertionTimeoutMs: 10_000,
138				fileSystem: witnessNodeFileSystem,
139				browser: host.browser,
140				headless: true,
141			});
142			status = result.status;
143			failure = result.boxes[0]?.error?.message ?? '';
144			receiptPath = result.receiptPath;
145		} finally {
146			await staticServer.close();
147		}
148		process.stdout.write(
149			`${canonicalize({
150				lane,
151				status,
152				failure,
153				receiptPath,
154				counts,
155				telemetry,
156				storage,
157				scroll,
158				requestOutcomes: host.requestOutcomes(),
159				staticPaths: staticServer.requests(),
160			})}\n`,
161		);
162	}
163	
164	export async function main(args = process.argv.slice(2)): Promise<void> {
165		const lane = args[0];
166		if (lane !== 'baseline' && lane !== 'migrated')
167			throw new Error('Super Productivity calibration requires a lane: baseline or migrated');
168		await calibrateAngularSuperProductivityLane(lane);
169	}
170	
171	if (basename(process.argv[1] ?? '') === 'angular-super-productivity-calibrate-run.ts')
172		main().catch((error: unknown) => {
173			process.stderr.write(`${error instanceof Error ? error.message : String(error)}\n`);
174			process.exitCode = 1;
175		});
