1	import { readFile } from 'node:fs/promises';
2	import { basename, isAbsolute, join, normalize } from 'pathe';
3	import type {
4		BrowserConsoleMessage,
5		BrowserLaunchOptions,
6		BrowserNetworkConditions,
7		BrowserNetworkRequest,
8		BrowserPageError,
9		BrowserRequestFailure,
10		WitnessBrowser,
11		WitnessBrowserPage,
12		WitnessBrowserSession,
13	} from '@async/witness';
14	import {
15		chromium,
16		type Browser,
17		type BrowserContext,
18		type BrowserContextOptions,
19		type CDPSession,
20		type Download,
21		type Page,
22		type Request,
23		type Route,
24	} from 'playwright';
25	import { parseHost, parseURL } from 'ufo';
26	import { sha256 } from '../../../core/src/receipts/canonicalize.ts';
27	
28	export type ServiceWorkerTelemetry = {
29		state: 'ready' | 'timeout';
30		registration: {
31			scriptPath: string | null;
32			scope: string | null;
33			installing: string | null;
34			waiting: string | null;
35			active: string | null;
36		};
37		controller: string | null;
38		cacheNames: string[];
39		cacheEntries: Array<{ name: string; paths: string[] }>;
40		workerEvents: Array<
41			| { kind: 'registration'; scopePath: string }
42			| { kind: 'version'; scriptPath: string; status: string; runningStatus: string }
43			| {
44					kind: 'error';
45					message: string;
46					sourcePath: string;
47					lineNumber: number;
48					columnNumber: number;
49			  }
50		>;
51	};
52	
53	export type WitnessTransportRequest = {
54		protocol: string;
55		host: string;
56		pathname: string;
57		search: string;
58		method: string;
59		resourceType: string;
60	};
61	
62	export type WitnessTransportDecision =
63		| { action: 'continue' }
64		| { action: 'fulfill'; status: number; contentType: string; body: Buffer };
65	
66	export type ServiceWorkerObserverFinalization = {
67		state: 'target-closed';
68		detach: 'owned-detach-complete';
69		pageClose: 'owned-page-close-complete';
70		workerEvents: ServiceWorkerTelemetry['workerEvents'];
71	};
72	
73	export type WitnessDifferentialEvent = {
74		sequence: number;
75		timestampMs: number;
76		source: 'browser' | 'context-route' | 'manifest' | 'static-server' | 'worker' | 'teardown';
77		phase: string;
78		urlPath: string | null;
79		detail: Record<string, boolean | number | string | null>;
80	};
81	
82	/** Document scroll extents and current offset, read from the live page. */
83	export type WitnessViewportScroll = {
84		scrollHeight: number;
85		clientHeight: number;
86		scrollY: number;
87	};
88	
89	/**
90	 * One request outcome as the page itself reported it, recorded synchronously in
91	 * the same event dispatch the linked Witness runtime records from.
92	 *
93	 * The runtime's own network record resolves each request's response
94	 * asynchronously, which is fine for a receipt written after the page closes but
95	 * useless for a question asked while the journey is still running. This ledger
96	 * exists so that "did this page also fetch that path successfully?" can be
97	 * answered against exactly the set of events the runtime's failed-request count
98	 * was computed from, with no window in which one has seen an event and the
99	 * other has not.
100	 */
101	export type WitnessObservedRequestOutcome = {
102		url: string;
103		method: string;
104		outcome: 'finished' | 'failed';
105		/** Response status for a finished request; null when the browser reported none. */
106		status: number | null;
107		/** The browser's own failure reason for a failed request; null otherwise. */
108		reason: string | null;
109	};
110	
111	/**
112	 * One rendered-appearance measurement to take from the live page: an element,
113	 * and the exact CSS properties whose resolved values are wanted. Nothing about
114	 * the stylesheet is read — these are the values the browser actually resolved
115	 * for a laid-out element, which is the only thing a reader of a styling claim
116	 * cares about.
117	 */
118	export type WitnessRenderedStyleProbe = {
119		label: string;
120		selector: string;
121		properties: readonly string[];
122	};
123	
124	/** The measurement itself, including the element's laid-out box in CSS pixels. */
125	export type WitnessRenderedStyle = {
126		label: string;
127		selector: string;
128		width: number;
129		height: number;
130		properties: Record<string, string>;
131	};
132	
133	/**
134	 * One grouped-text reading to take from the live page: the containers that make
135	 * up the groups, what names each group, and which elements inside a group are
136	 * its items.
137	 *
138	 * This is the reading counterpart of {@link WitnessRenderedStyleProbe}, and it
139	 * exists for the same reason. An application whose state lives in a store
140	 * renders that state as ordered lists — a kanban board, a grouped table, a
141	 * navigation tree — and the only way to record what the store settled to is to
142	 * read what the browser laid out. Assertions still go through `expect.page.*`;
143	 * this produces the evidence those assertions are about.
144	 */
145	export type WitnessGroupedTextProbe = {
146		/** Selector matching every group container, read in document order. */
147		group: string;
148		/** Selector, resolved inside a group, for the element that names it. */
149		name: string;
150		/**
151		 * When set, the group's name is this attribute of the name element rather
152		 * than its text — for a container whose visible label is interleaved with
153		 * other text, the attribute is the stable identity.
154		 */
155		nameAttribute?: string;
156		/** Selector, resolved inside a group, matching its items in document order. */
157		item: string;
158	};
159	
160	/** One group as the page rendered it: its name, and its items in order. */
161	export type WitnessGroupedText = { name: string; items: string[] };
162	
163	/**
164	 * One file-input surface an application declares, and the only way a file ever
165	 * reaches a page under this host.
166	 *
167	 * The declaration is the whole mechanism: it names the input the file is loaded
168	 * into and the fixture that is loaded into it, and the host will load that
169	 * fixture and nothing else. `fixturePath` is repository-relative on purpose —
170	 * it is copied verbatim into the evidence, and a host-specific absolute path has
171	 * no business in a published receipt. The absolute location it is read from is
172	 * the caller's declared root, which is never recorded.
173	 */
174	export type WitnessFileInputSurface = {
175		/** How the journey asks for this surface. Unique within an application. */
176		label: string;
177		selector: string;
178		/** Repository-relative path of the fixture handed to the page. */
179		fixturePath: string;
180	};
181	
182	/** The declared surfaces plus the absolute root the paths resolve against. */
183	export type WitnessFileInputDeclaration = {
184		/** Absolute directory the declared fixture paths resolve against. Never recorded. */
185		root: string;
186		surfaces: readonly WitnessFileInputSurface[];
187	};
188	
189	/** One load as it happened, recorded from the exact bytes handed to the page. */
190	export type WitnessLoadedFileInput = WitnessFileInputSurface & {
191		fileName: string;
192		bytes: number;
193		sha256: string;
194	};
195	
196	/** One download as the browser wrote it, read back rather than counted. */
197	export type WitnessCapturedDownload = {
198		suggestedFilename: string;
199		bytes: number;
200		sha256: string;
201	};
202	
203	/**
204	 * The browser-context options this host constructs, exposed rather than inlined
205	 * so the absence of a capability is checkable rather than merely intended: an
206	 * application that declares no download surface must produce options with no
207	 * `acceptDownloads` key at all, and that is a fact a test can hold.
208	 */
209	export function witnessBrowserContextOptions(options: {
210		serviceWorkers?: 'allow' | 'block';
211		viewport?: { width: number; height: number };
212		contextProfile?: 'current-witness' | 'canonical-t060';
213		downloads?: 'capture';
214	}): BrowserContextOptions {
215		return {
216			serviceWorkers: options.serviceWorkers ?? 'allow',
217			...(options.viewport === undefined ? {} : { viewport: options.viewport }),
218			...(options.contextProfile === 'canonical-t060'
219				? {
220						locale: 'en-US',
221						timezoneId: 'America/Chicago',
222						viewport: { width: 1280, height: 720 },
223					}
224				: {}),
225			// Granted only by declaration. Playwright's own default refuses
226			// downloads, so an application that declared none runs in a context that
227			// cannot complete one.
228			...(options.downloads === 'capture' ? { acceptDownloads: true } : {}),
229		};
230	}
231	
232	/**
233	 * The declared surfaces, checked as a declaration rather than trusted as one: a
234	 * surface with no label or selector, a duplicated label, or a fixture path that
235	 * is absolute or climbs out of the declared root is refused here rather than
236	 * being discovered in the evidence.
237	 */
238	export function validateWitnessFileInputDeclaration(
239		declaration: WitnessFileInputDeclaration,
240	): WitnessFileInputDeclaration {
241		if (!isAbsolute(declaration.root))
242			throw new Error('Witness file-input declaration needs an absolute fixture root');
243		if (declaration.surfaces.length === 0)
244			throw new Error('Witness file-input declaration names no surface');
245		const labels = new Set<string>();
246		for (const surface of declaration.surfaces) {
247			const relative = normalize(surface.fixturePath);
248			if (
249				surface.label.length === 0 ||
250				surface.selector.length === 0 ||
251				surface.fixturePath.length === 0 ||
252				isAbsolute(surface.fixturePath) ||
253				relative.startsWith('..')
254			)
255				throw new Error(`Witness file-input surface is malformed: ${surface.label}`);
256			if (labels.has(surface.label))
257				throw new Error(`Witness file-input surface is declared twice: ${surface.label}`);
258			labels.add(surface.label);
259		}
260		return declaration;
261	}
262	
263	/**
264	 * The declared surface a journey asked for. A journey that asks for a surface
265	 * the application never declared, or asks at all where nothing was declared,
266	 * gets an error rather than a silently skipped load.
267	 */
268	export function witnessFileInputSurface(
269		declaration: WitnessFileInputDeclaration | undefined,
270		label: string,
271	): WitnessFileInputSurface {
272		if (declaration === undefined)
273			throw new Error('Witness file-input mechanism is not declared by this application');
274		const surface = declaration.surfaces.find((candidate) => candidate.label === label);
275		if (surface === undefined)
276			throw new Error(`Witness file-input surface is not declared: ${label}`);
277		return surface;
278	}
279	
280	/** The record of a load, taken from the bytes themselves. */
281	export function recordWitnessLoadedFileInput(
282		surface: WitnessFileInputSurface,
283		bytes: Buffer,
284	): WitnessLoadedFileInput {
285		return {
286			label: surface.label,
287			selector: surface.selector,
288			fixturePath: surface.fixturePath,
289			fileName: basename(surface.fixturePath),
290			bytes: bytes.length,
291			sha256: sha256(bytes),
292		};
293	}
294	
295	/** The record of a download, taken from the bytes the browser wrote. */
296	export function recordWitnessCapturedDownload(
297		suggestedFilename: string,
298		bytes: Buffer,
299	): WitnessCapturedDownload {
300		if (suggestedFilename.length === 0)
301			throw new Error('Witness download capture read an unnamed download');
302		return { suggestedFilename, bytes: bytes.length, sha256: sha256(bytes) };
303	}
304	
305	export type PlaywrightWitnessHost = {
306		browser: WitnessBrowser;
307		locality(): { successfulNonLoopback: 0; mockedNonLoopback: number };
308		serviceWorkerTelemetry(timeoutMs: number): Promise<ServiceWorkerTelemetry>;
309		serviceWorkerObserverFinalization(): ServiceWorkerObserverFinalization;
310		/**
311		 * Measures the scrolling document so a scroll claim can be checked against
312		 * the surface that actually exists rather than asserted in the abstract.
313		 */
314		viewportScroll(): Promise<WitnessViewportScroll>;
315		/**
316		 * Reads resolved appearance for the named elements out of the live page, so a
317		 * claim about how an application renders is measured rather than asserted
318		 * from the bytes that were shipped.
319		 */
320		renderedStyles(probes: readonly WitnessRenderedStyleProbe[]): Promise<WitnessRenderedStyle[]>;
321		/**
322		 * Reads the ordered item text of every group the probe matches, so a claim
323		 * about what an application's own store settled to is recorded from the
324		 * rendered page rather than inferred from the gesture that provoked it.
325		 */
326		groupedText(probe: WitnessGroupedTextProbe): Promise<WitnessGroupedText[]>;
327		/**
328		 * The keys the page's own origin holds in browser storage, sorted. A claim
329		 * that an application persists nothing has to be measured against the
330		 * storage it would have written to, not asserted from its source.
331		 */
332		browserStorageKeys(): Promise<{ localStorage: string[]; sessionStorage: string[] }>;
333		/** Every request outcome the page reported, in observation order. */
334		requestOutcomes(): WitnessObservedRequestOutcome[];
335		/**
336		 * Hands the live page the fixture the named declared surface points at,
337		 * through the browser's own file-input mechanism, and records what was
338		 * handed over. Refuses where the application declared no such surface.
339		 */
340		loadFileInput(label: string): Promise<WitnessLoadedFileInput>;
341		/** Every load this run performed, in the order it performed them. */
342		loadedFileInputs(): WitnessLoadedFileInput[];
343		/**
344		 * Reads back every download the page produced. Refuses where the application
345		 * declared no download surface, because a context that never accepted
346		 * downloads has nothing to read back and saying otherwise would be a claim
347		 * about a mechanism that was not running.
348		 */
349		capturedDownloads(): Promise<WitnessCapturedDownload[]>;
350		/**
351		 * The decoded text of the same downloads, for a journey whose claim is about
352		 * what the produced file CONTAINS rather than about one having been produced.
353		 *
354		 * It is gated by the same declaration and reads the same already-captured
355		 * bytes; what it deliberately does not do is put the content into evidence.
356		 * A produced file is the application's own data — here, somebody's
357		 * translations — and the receipt records its name, length and digest. The
358		 * text exists so an assertion can be made against it and then discarded.
359		 */
360		capturedDownloadTexts(): Promise<string[]>;
361	};
