363	const MAX_TELEMETRY_TIMEOUT_MS = 15_000;
364	const MAX_TRANSPORT_BODY_BYTES = 1_048_576;
365	
366	export function validateWitnessTransportDecision(
367		decision: WitnessTransportDecision,
368	): WitnessTransportDecision {
369		if (decision.action === 'continue') return decision;
370		if (
371			!Number.isInteger(decision.status) ||
372			decision.status < 200 ||
373			decision.status > 599 ||
374			decision.contentType.length === 0 ||
375			decision.contentType.length > 128 ||
376			decision.body.length > MAX_TRANSPORT_BODY_BYTES
377		)
378			throw new Error('Witness transport fulfillment exceeds its fixed boundary');
379		return decision;
380	}
