382	export function validateWitnessQualificationTypingMode(options: {
383		clear: boolean;
384		keyEvents: boolean;
385	}): void {
386		if (options.clear || !options.keyEvents)
387			throw new Error('Witness qualification host rejects fill-backed typing modes');
388	}
389	
390	function boundedTelemetryTimeout(timeoutMs: number): number {
391		if (!Number.isInteger(timeoutMs) || timeoutMs < 1 || timeoutMs > MAX_TELEMETRY_TIMEOUT_MS)
392			throw new Error('Witness service-worker telemetry timeout is outside its fixed boundary');
393		return timeoutMs;
394	}
