396	async function observeServiceWorkers(
397		cdp: CDPSession,
398		page: Page,
399		workerEvents: ServiceWorkerTelemetry['workerEvents'],
400		diagnosticEvent?: (event: Omit<WitnessDifferentialEvent, 'sequence' | 'timestampMs'>) => void,
401	): Promise<{
402		finalize(): Promise<void>;
403		readback(): ServiceWorkerObserverFinalization | null;
404	}> {
405		let state: 'attached' | 'finalizing' | 'detached' | 'target-closed' = 'attached';
406		const observerState = (): typeof state => state;
407		let finalization: ServiceWorkerObserverFinalization | null = null;
408		const onRegistrationUpdated = (event: unknown): void => {
409			const registrations = (event as { registrations?: Array<{ scopeURL?: string }> })
410				.registrations;
411			for (const registration of registrations ?? []) {
412				diagnosticEvent?.({
413					source: 'worker',
414					phase: 'registration',
415					urlPath: parseURL(registration.scopeURL ?? '').pathname || '',
416					detail: {},
417				});
418				workerEvents.push({
419					kind: 'registration',
420					scopePath: parseURL(registration.scopeURL ?? '').pathname || '',
421				});
422			}
423		};
424		const onVersionUpdated = (event: unknown): void => {
425			const versions = (
426				event as {
427					versions?: Array<{
428						scriptURL?: string;
429						status?: string;
430						runningStatus?: string;
431					}>;
432				}
433			).versions;
434			for (const version of versions ?? []) {
435				diagnosticEvent?.({
436					source: 'worker',
437					phase: 'version',
438					urlPath: parseURL(version.scriptURL ?? '').pathname || '',
439					detail: {
440						status: version.status ?? 'unknown',
441						runningStatus: version.runningStatus ?? 'unknown',
442					},
443				});
444				workerEvents.push({
445					kind: 'version',
446					scriptPath: parseURL(version.scriptURL ?? '').pathname || '',
447					status: version.status ?? 'unknown',
448					runningStatus: version.runningStatus ?? 'unknown',
449				});
450			}
451		};
452		const onWorkerError = (event: unknown): void => {
453			const nested = (event as { errorMessage?: unknown }).errorMessage;
454			const report =
455				nested !== null && typeof nested === 'object'
456					? (nested as Record<string, unknown>)
457					: (event as Record<string, unknown>);
458			workerEvents.push({
459				kind: 'error',
460				message: typeof report.errorMessage === 'string' ? report.errorMessage : 'unknown',
461				sourcePath:
462					typeof report.sourceURL === 'string'
463						? parseURL(report.sourceURL).pathname || ''
464						: '',
465				lineNumber: typeof report.lineNumber === 'number' ? report.lineNumber : 0,
466				columnNumber: typeof report.columnNumber === 'number' ? report.columnNumber : 0,
467			});
468			diagnosticEvent?.({
469				source: 'worker',
470				phase: 'error',
471				urlPath:
472					typeof report.sourceURL === 'string'
473						? parseURL(report.sourceURL).pathname || ''
474						: '',
475				detail: {
476					message: typeof report.errorMessage === 'string' ? report.errorMessage : 'unknown',
477				},
478			});
479		};
480		const onTargetClosed = (): void => {
481			if (state !== 'detached')
482				throw new Error(`Witness service-worker observer target closed while ${state}`);
483			state = 'target-closed';
484		};
485		cdp.on('ServiceWorker.workerRegistrationUpdated', onRegistrationUpdated);
486		cdp.on('ServiceWorker.workerVersionUpdated', onVersionUpdated);
487		cdp.on('ServiceWorker.workerErrorReported', onWorkerError);
488		page.on('close', onTargetClosed);
489		await cdp.send('ServiceWorker.enable');
490		return {
491			finalize: async () => {
492				if (state !== 'attached')
493					throw new Error(`Witness service-worker observer duplicate finalization: ${state}`);
494				if (page.isClosed())
495					throw new Error(
496						'Witness service-worker observer target closed before finalization',
497					);
498				state = 'finalizing';
499				diagnosticEvent?.({ source: 'teardown', phase: 'freeze', urlPath: null, detail: {} });
500				const snapshot = Object.freeze(
501					structuredClone(workerEvents).sort((left, right) =>
502						JSON.stringify(left).localeCompare(JSON.stringify(right)),
503					),
504				);
505				cdp.off('ServiceWorker.workerRegistrationUpdated', onRegistrationUpdated);
506				cdp.off('ServiceWorker.workerVersionUpdated', onVersionUpdated);
507				cdp.off('ServiceWorker.workerErrorReported', onWorkerError);
508				await cdp.detach();
509				state = 'detached';
510				diagnosticEvent?.({ source: 'teardown', phase: 'detached', urlPath: null, detail: {} });
511				await page.close();
512				page.off('close', onTargetClosed);
513				if (observerState() !== 'target-closed')
514					throw new Error('Witness service-worker observer missed the owned page close');
515				finalization = {
516					state: 'target-closed',
517					detach: 'owned-detach-complete',
518					pageClose: 'owned-page-close-complete',
519					workerEvents: [...snapshot],
520				};
521				diagnosticEvent?.({
522					source: 'teardown',
523					phase: 'target-closed',
524					urlPath: null,
525					detail: {},
526				});
527			},
528			readback: () => (finalization === null ? null : structuredClone(finalization)),
529		};
530	}
