532	/**
533	 * Whether a URL addresses the bounded loopback origin the harness itself
534	 * serves. It is the one distinction that decides how a request is answered and
535	 * how it is written down, so it is exported rather than re-derived: the request
536	 * ledger records a loopback path exactly as requested and a non-loopback one
537	 * query-free, and both readings have to agree about which is which.
538	 */
539	export function isWitnessLoopbackUrl(url: string): boolean {
540		const hostname = parseHost(parseURL(url).host ?? '').hostname;
541		return hostname === '127.0.0.1' || hostname === 'localhost' || hostname === '::1';
542	}
543	
544	function modifiers(mask: number): string[] {
545		return [
546			...(mask & 1 ? ['Alt'] : []),
547			...(mask & 2 ? ['Control'] : []),
548			...(mask & 4 ? ['Meta'] : []),
549			...(mask & 8 ? ['Shift'] : []),
550		];
551	}
552	
553	function keyWithModifiers(key: string, mask: number): string {
554		return [...modifiers(mask), key].join('+');
555	}
556	
557	async function requestRecord(request: Request, startedAt: number): Promise<BrowserNetworkRequest> {
558		const response = await request.response();
559		return {
560			url: request.url(),
561			method: request.method(),
562			resourceType: request.resourceType(),
563			startTimeMs: startedAt,
564			responseTimeMs: response === null ? null : Date.now(),
565			endTimeMs: Date.now(),
566			durationMs: Date.now() - startedAt,
567			status: response?.status() ?? null,
568			mimeType: response?.headers()['content-type'] ?? null,
569			encodedDataLength: null,
570			failedReason: request.failure()?.errorText ?? null,
571			initiatorType: null,
572		};
573	}
574	
575	async function waitForScrollableChange(
576		page: Page,
577		target: string | null,
578		deltaX: number,
579		deltaY: number,
580		timeoutMs: number,
581	): Promise<void> {
582		const expression =
583			target === null
584				? '({ x: window.scrollX, y: window.scrollY })'
585				: `(() => { const element = document.querySelector(${JSON.stringify(target)}); return element === null ? null : { x: element.scrollLeft, y: element.scrollTop }; })()`;
586		const before = (await page.evaluate(expression)) as { x: number; y: number } | null;
587		if (target !== null) await page.locator(target).first().hover({ timeout: timeoutMs });
588		await page.mouse.wheel(deltaX, deltaY);
589		await page.waitForFunction(
590			({ stateExpression, previous }) => {
591				const current = globalThis.eval(stateExpression) as { x: number; y: number } | null;
592				return (
593					current !== null &&
594					(previous === null || current.x !== previous.x || current.y !== previous.y)
595				);
596			},
597			{ stateExpression: expression, previous: before },
598			{ timeout: timeoutMs },
599		);
600	}
601	
602	function adaptPage(
603		page: Page,
604		closePage: () => Promise<void>,
605		navigationWaitUntil: 'domcontentloaded' | 'networkidle',
606		requestOutcomes: WitnessObservedRequestOutcome[],
607	): WitnessBrowserPage {
608		const consoleListeners: Array<(message: BrowserConsoleMessage) => void> = [];
609		const pageErrorListeners: Array<(error: BrowserPageError) => void> = [];
610		const failureListeners: Array<(failure: BrowserRequestFailure) => void> = [];
611		const requestListeners: Array<(request: BrowserNetworkRequest) => void> = [];
612		const navigationListeners: Array<(url: string) => void> = [];
613		const requestStarts = new WeakMap<Request, number>();
614		/**
615		 * Response status captured the moment the headers arrive, so a finished
616		 * outcome can be recorded below without awaiting anything.
617		 */
618		const responseStatus = new WeakMap<Request, number>();
619		page.on('console', (message) => {
620			for (const listener of consoleListeners)
621				listener({ level: message.type(), text: message.text() });
622		});
623		page.on('pageerror', (error) => {
624			for (const listener of pageErrorListeners) listener({ message: error.message });
625		});
626		page.on('request', (request) => requestStarts.set(request, Date.now()));
627		page.on('response', (response) => responseStatus.set(response.request(), response.status()));
628		page.on('requestfailed', (request) => {
629			const failure = {
630				url: request.url(),
631				method: request.method(),
632				reason: request.failure()?.errorText ?? null,
633			};
634			// Recorded before the listeners run, so nothing reading this ledger can
635			// observe a failure the linked Witness record has not also observed.
636			requestOutcomes.push({ ...failure, outcome: 'failed', status: null });
637			for (const listener of failureListeners) listener(failure);
638			void requestRecord(request, requestStarts.get(request) ?? Date.now()).then((record) => {
639				for (const listener of requestListeners) listener(record);
640			});
641		});
642		page.on('requestfinished', (request) => {
643			requestOutcomes.push({
644				url: request.url(),
645				method: request.method(),
646				outcome: 'finished',
647				status: responseStatus.get(request) ?? null,
648				reason: null,
649			});
650			void requestRecord(request, requestStarts.get(request) ?? Date.now()).then((record) => {
651				for (const listener of requestListeners) listener(record);
652			});
653		});
654		page.on('framenavigated', (frame) => {
655			if (frame === page.mainFrame())
656				for (const listener of navigationListeners) listener(frame.url());
657		});
658		return {
659			goto: async (url) => void (await page.goto(url, { waitUntil: navigationWaitUntil })),
660			reload: async () => void (await page.reload({ waitUntil: navigationWaitUntil })),
661			content: () => page.content(),
662			screenshot: async (filePath) => void (await page.screenshot({ path: filePath })),
663			evaluate: (expression) => page.evaluate(expression),
664			waitForExpression: async (expression, timeoutMs) =>
665				void (await page.waitForFunction(expression, undefined, { timeout: timeoutMs })),
666			click: async (selector, timeoutMs) =>
667				void (await page.locator(selector).first().click({ timeout: timeoutMs })),
668			type: async (selector, text, options, timeoutMs) => {
669				const locator = page.locator(selector).first();
670				const type = await locator.getAttribute('type');
671				validateWitnessQualificationTypingMode(options);
672				for (const character of text) await locator.press(character, { timeout: timeoutMs });
673				return { passwordField: type === 'password' };
674			},
675			hover: async (selector, modifierMask, timeoutMs) =>
676				void (await page
677					.locator(selector)
678					.first()
679					.hover({
680						modifiers: modifiers(modifierMask) as Array<
681							'Alt' | 'Control' | 'Meta' | 'Shift'
682						>,
683						timeout: timeoutMs,
684					})),
685			press: async (selector, key, modifierMask, timeoutMs) =>
686				void (await page.locator(selector).first().press(keyWithModifiers(key, modifierMask), {
687					timeout: timeoutMs,
688				})),
689			drag: async (from, to, steps, timeoutMs) => {
690				const source = page.locator(from).first();
691				await source.scrollIntoViewIfNeeded({ timeout: timeoutMs });
692				const sourceBox = await source.boundingBox({ timeout: timeoutMs });
693				if (sourceBox === null)
694					throw new Error(`drag('${from}') found no laid-out source element`);
695				const destination = await (async (): Promise<{ x: number; y: number }> => {
696					if (typeof to !== 'string') return to;
697					const target = page.locator(to).first();
698					await target.scrollIntoViewIfNeeded({ timeout: timeoutMs });
699					const targetBox = await target.boundingBox({ timeout: timeoutMs });
700					if (targetBox === null)
701						throw new Error(`drag('${from}' -> '${to}') found no laid-out target element`);
702					const viewport = page.viewportSize();
703					const centre = targetBox.y + targetBox.height / 2;
704					return {
705						x: targetBox.x + targetBox.width / 2,
706						// A drop list taller than the viewport has its geometric centre
707						// off-screen; the pointer has to stay inside the window it is
708						// gesturing in, so the drop point is clamped into it.
709						y:
710							viewport === null
711								? centre
712								: Math.min(Math.max(centre, targetBox.y + 8), viewport.height - 8),
713					};
714				})();
715				const origin = {
716					x: sourceBox.x + sourceBox.width / 2,
717					y: sourceBox.y + sourceBox.height / 2,
718				};
719				await page.mouse.move(origin.x, origin.y);
720				await page.mouse.down();
721				// Interpolated intermediate moves: pointer-based drag libraries only
722				// begin tracking after movement past their own threshold, so a single
723				// jump from source to destination is not a drag they ever observe.
724				for (let step = 1; step <= steps; step += 1)
725					await page.mouse.move(
726						origin.x + (destination.x - origin.x) * (step / steps),
727						origin.y + (destination.y - origin.y) * (step / steps),
728					);
729				await page.mouse.up();
730			},
731			scroll: async (target, deltaX, deltaY, _gesture, timeoutMs) =>
732				waitForScrollableChange(page, target, deltaX, deltaY, timeoutMs),
733			onConsoleMessage: (listener) => void consoleListeners.push(listener),
734			onPageError: (listener) => void pageErrorListeners.push(listener),
735			onRequestFailed: (listener) => void failureListeners.push(listener),
736			onNetworkRequest: (listener) => void requestListeners.push(listener),
737			emulateNetwork: async (conditions: BrowserNetworkConditions) =>
738				void (await page.context().setOffline(conditions.offline === true)),
739			clearNetworkEmulation: async () => void (await page.context().setOffline(false)),
740			onNavigated: (listener) => void navigationListeners.push(listener),
741			close: closePage,
742		};
743	}
