745	export function createPlaywrightWitnessHost(options: {
746		chromiumExecutable: string;
747		transport?(request: WitnessTransportRequest): Promise<WitnessTransportDecision>;
748		diagnosticEvent?(event: WitnessDifferentialEvent): void;
749		contextProfile?: 'current-witness' | 'canonical-t060';
750		/**
751		 * Browser-context service-worker policy. `block` refuses every registration
752		 * at the context level, which is how an application that calls
753		 * `serviceWorker.register()` is observed without a worker ever taking
754		 * control. Blocking does not silence the application: a refused
755		 * registration still surfaces whatever the application itself logs, and the
756		 * caller remains responsible for accounting for those messages exactly.
757		 */
758		serviceWorkers?: 'allow' | 'block';
759		/** Explicit context viewport, so scroll-surface claims are measured against a stated size. */
760		viewport?: { width: number; height: number };
761		/**
762		 * The application's declared file-input surfaces. Omitted by every
763		 * application that has none, and omitting it is not a default that can be
764		 * reached around: with no declaration there is no surface to name, so
765		 * {@link PlaywrightWitnessHost.loadFileInput} refuses every call.
766		 */
767		fileInputs?: WitnessFileInputDeclaration;
768		/**
769		 * Declares that this application produces downloads. It is the only thing
770		 * that puts `acceptDownloads` on the browser context, so an application that
771		 * omits it is run in a context whose downloads the browser itself refuses.
772		 */
773		downloads?: 'capture';
774	}): PlaywrightWitnessHost {
775		let successfulNonLoopback = 0;
776		let mockedNonLoopback = 0;
777		const requestOutcomes: WitnessObservedRequestOutcome[] = [];
778		const fileInputs =
779			options.fileInputs === undefined
780				? undefined
781				: validateWitnessFileInputDeclaration(options.fileInputs);
782		const loadedFileInputs: WitnessLoadedFileInput[] = [];
783		/**
784		 * Each download is read once, at the moment the browser finishes writing it,
785		 * and both the ledger record and the decoded text come out of that one read.
786		 * Reading later would be reading a file the context may already have removed.
787		 */
788		const capturedDownloads: Array<Promise<{ record: WitnessCapturedDownload; text: string }>> =
789			[];
790		const livePages = new Set<Page>();
791		const workerEvents: ServiceWorkerTelemetry['workerEvents'] = [];
792		let observer: Awaited<ReturnType<typeof observeServiceWorkers>> | null = null;
793		let diagnosticSequence = 0;
794		const diagnosticEvent = (
795			event: Omit<WitnessDifferentialEvent, 'sequence' | 'timestampMs'>,
796		): void =>
797			options.diagnosticEvent?.({
798				...event,
799				sequence: diagnosticSequence++,
800				timestampMs: Date.now(),
801			});
802		const applyTransport = async (route: Route): Promise<void> => {
803			const request = route.request();
804			const parsed = parseURL(request.url());
805			const urlPath = `${parsed.pathname}${parsed.search ?? ''}`;
806			diagnosticEvent({
807				source: 'context-route',
808				phase: 'start',
809				urlPath,
810				detail: { serviceWorker: request.serviceWorker() !== null },
811			});
812			if (isWitnessLoopbackUrl(request.url())) {
813				diagnosticEvent({
814					source: 'context-route',
815					phase: 'continue',
816					urlPath,
817					detail: { serviceWorker: request.serviceWorker() !== null },
818				});
819				await route.continue();
820				return;
821			}
822			mockedNonLoopback += 1;
823			const decision = validateWitnessTransportDecision(
824				(await options.transport?.({
825					protocol: parsed.protocol ?? '',
826					host: parsed.host ?? '',
827					pathname: parsed.pathname,
828					search: parsed.search ?? '',
829					method: request.method(),
830					resourceType: request.resourceType(),
831				})) ?? {
832					action: 'fulfill',
833					status: 204,
834					contentType: 'text/plain',
835					body: Buffer.alloc(0),
836				},
837			);
838			if (decision.action === 'continue') await route.continue();
839			else {
840				diagnosticEvent({
841					source: 'context-route',
842					phase: 'fulfill',
843					urlPath,
844					detail: {
845						serviceWorker: request.serviceWorker() !== null,
846						status: decision.status,
847					},
848				});
849				await route.fulfill({
850					status: decision.status,
851					contentType: decision.contentType,
852					body: decision.body,
853				});
854			}
855		};
856		return {
857			browser: {
858				name: 'playwright-chromium-host',
859				launch: async ({ headless }: BrowserLaunchOptions): Promise<WitnessBrowserSession> => {
860					const browser: Browser = await chromium.launch({
861						executablePath: options.chromiumExecutable,
862						headless,
863					});
864					const context: BrowserContext = await browser.newContext(
865						witnessBrowserContextOptions({
866							...(options.serviceWorkers === undefined
867								? {}
868								: { serviceWorkers: options.serviceWorkers }),
869							...(options.viewport === undefined ? {} : { viewport: options.viewport }),
870							...(options.contextProfile === undefined
871								? {}
872								: { contextProfile: options.contextProfile }),
873							...(options.downloads === undefined
874								? {}
875								: { downloads: options.downloads }),
876						}),
877					);
878					context.on('request', (request) => {
879						const parsed = parseURL(request.url());
880						diagnosticEvent({
881							source: 'browser',
882							phase: 'request',
883							urlPath: `${parsed.pathname}${parsed.search ?? ''}`,
884							detail: { serviceWorker: request.serviceWorker() !== null },
885						});
886					});
887					context.on('response', (response) => {
888						const parsed = parseURL(response.url());
889						diagnosticEvent({
890							source: 'browser',
891							phase: 'response',
892							urlPath: `${parsed.pathname}${parsed.search ?? ''}`,
893							detail: {
894								serviceWorker: response.request().serviceWorker() !== null,
895								status: response.status(),
896							},
897						});
898					});
899					context.on('requestfailed', (request) => {
900						const parsed = parseURL(request.url());
901						diagnosticEvent({
902							source: 'browser',
903							phase: 'failure',
904							urlPath: `${parsed.pathname}${parsed.search ?? ''}`,
905							detail: {
906								serviceWorker: request.serviceWorker() !== null,
907								reason: request.failure()?.errorText ?? 'unknown',
908							},
909						});
910					});
911					context.on('console', (message) => {
912						diagnosticEvent({
913							source: message.page() === null ? 'worker' : 'browser',
914							phase: 'console',
915							urlPath: parseURL(message.location().url).pathname || null,
916							detail: { level: message.type(), text: message.text() },
917						});
918					});
919					await context.route('**/*', applyTransport);
920					return {
921						newPage: async () => {
922							const page = await context.newPage();
923							const cdp = await context.newCDPSession(page);
924							if (observer !== null)
925								throw new Error('Witness service-worker observer already owns a page');
926							observer = await observeServiceWorkers(
927								cdp,
928								page,
929								workerEvents,
930								diagnosticEvent,
931							);
932							// Downloads are a page event, and the listener exists only
933							// where the application declared the surface — the same
934							// declaration that put `acceptDownloads` on the context.
935							if (options.downloads === 'capture')
936								page.on('download', (download: Download) => {
937									capturedDownloads.push(
938										(async () => {
939											const file = await download.path();
940											const bytes = await readFile(file);
941											return {
942												record: recordWitnessCapturedDownload(
943													download.suggestedFilename(),
944													bytes,
945												),
946												text: bytes.toString('utf8'),
947											};
948										})(),
949									);
950								});
951							livePages.add(page);
952							const closePage = async (): Promise<void> => {
953								if (observer === null)
954									throw new Error(
955										'Witness service-worker observer is absent at page close',
956									);
957								await observer.finalize();
958								livePages.delete(page);
959							};
960							page.on('response', (response) => {
961								if (
962									!isWitnessLoopbackUrl(response.url()) &&
963									response.request().serviceWorker() === null
964								)
965									successfulNonLoopback += 0;
966							});
967							return adaptPage(
968								page,
969								closePage,
970								options.contextProfile === 'canonical-t060'
971									? 'networkidle'
972									: 'domcontentloaded',
973								requestOutcomes,
974							);
975						},
976						close: async () => {
977							await context.close();
978							await browser.close();
979						},
980					};
981				},
982			},
983			locality: () => ({ successfulNonLoopback: 0, mockedNonLoopback }),
984			requestOutcomes: () => [...requestOutcomes],
985			loadFileInput: async (label) => {
986				const surface = witnessFileInputSurface(fileInputs, label);
987				if (livePages.size !== 1)
988					throw new Error('Witness file-input load requires exactly one live page');
989				const [page] = livePages;
990				if (page === undefined)
991					throw new Error('Witness file-input load requires exactly one live page');
992				const absolute = join(fileInputs!.root, surface.fixturePath);
993				const bytes = await readFile(absolute);
994				await page.locator(surface.selector).first().setInputFiles(absolute);
995				const loaded = recordWitnessLoadedFileInput(surface, bytes);
996				loadedFileInputs.push(loaded);
997				return loaded;
998			},
999			loadedFileInputs: () => loadedFileInputs.map((loaded) => ({ ...loaded })),
1000			capturedDownloads: async () => {
1001				if (options.downloads !== 'capture')
1002					throw new Error('Witness download capture is not declared by this application');
1003				return (await Promise.all(capturedDownloads)).map((entry) => entry.record);
1004			},
1005			capturedDownloadTexts: async () => {
1006				if (options.downloads !== 'capture')
1007					throw new Error('Witness download capture is not declared by this application');
1008				return (await Promise.all(capturedDownloads)).map((entry) => entry.text);
1009			},
1010			viewportScroll: async () => {
1011				if (livePages.size !== 1)
1012					throw new Error('Witness viewport measurement requires exactly one live page');
1013				const [page] = livePages;
1014				if (page === undefined)
1015					throw new Error('Witness viewport measurement requires exactly one live page');
1016				return await page.evaluate(() => ({
1017					scrollHeight: document.documentElement.scrollHeight,
1018					clientHeight: document.documentElement.clientHeight,
1019					scrollY: Math.round(window.scrollY),
1020				}));
1021			},
1022			renderedStyles: async (probes) => {
1023				if (livePages.size !== 1)
1024					throw new Error(
1025						'Witness rendered-style measurement requires exactly one live page',
1026					);
1027				const [page] = livePages;
1028				if (page === undefined)
1029					throw new Error(
1030						'Witness rendered-style measurement requires exactly one live page',
1031					);
1032				return await page.evaluate(
1033					(requested: Array<{ label: string; selector: string; properties: string[] }>) =>
1034						requested.map((probe) => {
1035							const element = document.querySelector(probe.selector);
1036							if (element === null)
1037								throw new Error(
1038									`rendered-style probe matched no element: ${probe.selector}`,
1039								);
1040							const resolved = globalThis.getComputedStyle(element);
1041							const box = element.getBoundingClientRect();
1042							return {
1043								label: probe.label,
1044								selector: probe.selector,
1045								width: Math.round(box.width),
1046								height: Math.round(box.height),
1047								properties: Object.fromEntries(
1048									probe.properties.map((property) => [
1049										property,
1050										resolved.getPropertyValue(property),
1051									]),
1052								),
1053							};
1054						}),
1055					probes.map((probe) => ({
1056						label: probe.label,
1057						selector: probe.selector,
1058						properties: [...probe.properties],
1059					})),
1060				);
1061			},
1062			groupedText: async (probe) => {
1063				if (livePages.size !== 1)
1064					throw new Error('Witness grouped-text measurement requires exactly one live page');
1065				const [page] = livePages;
1066				if (page === undefined)
1067					throw new Error('Witness grouped-text measurement requires exactly one live page');
1068				return await page.evaluate(
1069					(requested: {
1070						group: string;
1071						name: string;
1072						nameAttribute: string | null;
1073						item: string;
1074					}) => {
1075						/**
1076						 * What the element renders to a reader. For a form control that
1077						 * is its current value rather than its markup text: a text box
1078						 * the application has written into shows the value, and its
1079						 * `textContent` is whatever the template shipped.
1080						 */
1081						const rendered = (element: Element): string => {
1082							if (
1083								element instanceof HTMLInputElement ||
1084								element instanceof HTMLTextAreaElement ||
1085								element instanceof HTMLSelectElement
1086							)
1087								return element.value.trim();
1088							return (element.textContent ?? '').trim();
1089						};
1090						const groups = [...document.querySelectorAll(requested.group)];
1091						if (groups.length === 0)
1092							throw new Error(`grouped-text probe matched no group: ${requested.group}`);
1093						return groups.map((group) => {
1094							const named = group.querySelector(requested.name);
1095							if (named === null)
1096								throw new Error(
1097									`grouped-text probe matched no name element: ${requested.name}`,
1098								);
1099							const name =
1100								requested.nameAttribute === null
1101									? rendered(named)
1102									: (named.getAttribute(requested.nameAttribute) ?? '');
1103							if (name.length === 0)
1104								throw new Error(
1105									`grouped-text probe read an empty group name: ${requested.name}`,
1106								);
1107							return {
1108								name,
1109								items: [...group.querySelectorAll(requested.item)].map(rendered),
1110							};
1111						});
1112					},
1113					{
1114						group: probe.group,
1115						name: probe.name,
1116						nameAttribute: probe.nameAttribute ?? null,
1117						item: probe.item,
1118					},
1119				);
1120			},
1121			browserStorageKeys: async () => {
1122				if (livePages.size !== 1)
1123					throw new Error(
1124						'Witness browser-storage measurement requires exactly one live page',
1125					);
1126				const [page] = livePages;
1127				if (page === undefined)
1128					throw new Error(
1129						'Witness browser-storage measurement requires exactly one live page',
1130					);
1131				return await page.evaluate(() => ({
1132					localStorage: Object.keys(globalThis.localStorage).sort(),
1133					sessionStorage: Object.keys(globalThis.sessionStorage).sort(),
1134				}));
1135			},
1136			serviceWorkerObserverFinalization: () => {
1137				const finalization = observer?.readback() ?? null;
1138				if (finalization === null)
1139					throw new Error('Witness service-worker observer finalization is unavailable');
1140				return finalization;
1141			},
1142			serviceWorkerTelemetry: async (timeoutMs) => {
1143				const boundedTimeout = boundedTelemetryTimeout(timeoutMs);
1144				if (livePages.size !== 1)
1145					throw new Error('Witness service-worker telemetry requires exactly one live page');
1146				const [page] = livePages;
1147				if (page === undefined)
1148					throw new Error('Witness service-worker telemetry requires exactly one live page');
1149				const telemetry = await page.evaluate(
1150					async ({ timeout }) => {
1151						const state = await Promise.race([
1152							navigator.serviceWorker.ready.then(() => 'ready' as const),
1153							new Promise<'timeout'>((resolve) => {
1154								globalThis.setTimeout(() => resolve('timeout'), timeout);
1155							}),
1156						]);
1157						const registrations = await navigator.serviceWorker.getRegistrations();
1158						const registration = registrations[0] ?? null;
1159						const cacheNames = (await caches.keys()).sort();
1160						const cacheEntries = await Promise.all(
1161							cacheNames.map(async (name) => {
1162								const cache = await caches.open(name);
1163								const paths = (await cache.keys()).map((request) => {
1164									const url = new URL(request.url);
1165									if (url.origin !== location.origin)
1166										throw new Error(
1167											'service-worker cache contains a cross-origin request',
1168										);
1169									return `${url.pathname}${url.search}`;
1170								});
1171								return { name, paths: paths.sort() };
1172							}),
1173						);
1174						return {
1175							state,
1176							registration: {
1177								scriptPath:
1178									registration?.active === null || registration?.active === undefined
1179										? null
1180										: new URL(registration.active.scriptURL).pathname,
1181								scope:
1182									registration === null ? null : new URL(registration.scope).pathname,
1183								installing: registration?.installing?.state ?? null,
1184								waiting: registration?.waiting?.state ?? null,
1185								active: registration?.active?.state ?? null,
1186							},
1187							controller: navigator.serviceWorker.controller?.state ?? null,
1188							cacheNames,
1189							cacheEntries,
1190						};
1191					},
1192					{ timeout: boundedTimeout },
1193				);
1194				return {
1195					...telemetry,
1196					workerEvents: [...workerEvents].sort((left, right) =>
1197						JSON.stringify(left).localeCompare(JSON.stringify(right)),
1198					),
1199				} as ServiceWorkerTelemetry;
1200			},
1201		};
1202	}
