		},
		serviceWorkerTelemetry: async (timeoutMs) => {
			const boundedTimeout = boundedTelemetryTimeout(timeoutMs);
			if (livePages.size !== 1)
				throw new Error('Witness service-worker telemetry requires exactly one live page');
			const [page] = livePages;
			if (page === undefined)
				throw new Error('Witness service-worker telemetry requires exactly one live page');
