641		result: 'pass';
642		provenance: Record<string, unknown>;
643		canonicalReceipts: Array<{
644			app: string;
645			path: string;
646			sha256: string;
647			canonicalDigest: string;
648		}>;
649		runs: WitnessRealAppRun[];
