663	function record(value: unknown, label: string): Record<string, unknown> {
664		if (value === null || typeof value !== 'object' || Array.isArray(value))
665			throw new Error(`Witness real-app ${label} must be an object`);
666		return value as Record<string, unknown>;
667	}
668	
669	function sha256Digest(value: unknown): value is string {
670		return typeof value === 'string' && value.length === 64;
671	}
672	
673	function sortedUniqueStrings(values: unknown): values is string[] {
674		return (
675			Array.isArray(values) &&
676			values.every((value) => typeof value === 'string') &&
677			new Set(values).size === values.length &&
678			values.join('\n') === [...values].sort().join('\n')
679		);
680	}
