682	function validServiceWorkerTelemetry(value: unknown): value is WitnessServiceWorkerTelemetry {
683		const telemetry = value as WitnessServiceWorkerTelemetry;
684		return (
685			telemetry?.state === 'ready' &&
686			telemetry.registration?.scriptPath === '/sw.js' &&
687			telemetry.registration.scope === '/' &&
688			telemetry.registration.active === 'activated' &&
689			(telemetry.controller === 'activated' || telemetry.controller === null) &&
690			sortedUniqueStrings(telemetry.cacheNames) &&
691			telemetry.cacheNames.length === 1 &&
692			Array.isArray(telemetry.cacheEntries) &&
693			telemetry.cacheEntries.length === 1 &&
694			telemetry.cacheEntries[0]?.name === telemetry.cacheNames[0] &&
695			sortedUniqueStrings(telemetry.cacheEntries[0].paths) &&
696			telemetry.cacheEntries[0].paths.length > 0 &&
697			telemetry.cacheEntries[0].paths.every((path) => path.startsWith('/')) &&
698			Array.isArray(telemetry.workerEvents)
