			run.result !== 'pass' ||
			run.cleanPage !== true ||
			run.successfulNonLoopback !== 0 ||
			run.witnessRecord.pageErrors !== 0 ||
			run.witnessRecord.consoleErrors !== run.consoleErrorInventory?.total ||
			run.witnessRecord.failedRequests !== run.failedRequestInventory?.total ||

