	)
		throw new Error(
			`refused-service-worker checkpoint failed: ${phase} ${canonicalize(telemetry)}`,
		);
	return {
		phase,
		state: 'timeout',
		registrations: 0,
		controller: null,
		cacheNames: [],
		attemptEvents,
	};
